"use client";

import { CheckCircle, XCircle, Clock } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { DashboardAdminService } from "@/data/api-client";
import { ApiResponse, getErrorMessage } from "@/lib/apiClient";
import { useLanguage } from "@/contexts/LanguageContext";
import { useRouter } from "next/navigation";

interface UseBookingDetailsParams {
  reservationId: number;
}

export interface BookingDetailsResponse {
  reservation: any;
  media: any;
  user: any;
  paymentPlan: any;
  country: any;
  property: any;
  [key: string]: any;
}

interface UseBookingDetailsReturn {
  bookingData: BookingDetailsResponse | undefined;
  reservationData?: BookingDetailsResponse | undefined;
  isLoading: boolean;
  isError: boolean;
  error: unknown;
  refetch: () => void;

  approveMutation: ReturnType<
    typeof useMutation<any, unknown, any>
  >;
  mutationApprove?: any;

  declineMutation: ReturnType<
    typeof useMutation<any, unknown, any>
  >;
  mutationDecline?: any;

  uploadSalesOfferMutation: ReturnType<
    typeof useMutation<
      ApiResponse<unknown>,
      unknown,
      any
    >
  >;
  mutationSalesOffer?: any;

  uploadSPAMutation: ReturnType<
    typeof useMutation<
      ApiResponse<unknown>,
      unknown,
      any
    >
  >;
  mutationSPA?: any;

  approveDownPaymentMutation: ReturnType<
    typeof useMutation<any, unknown, any>
  >;
  mutationDownPayment?: any;

  uploadDownPaymentMutation?: any;
  mutationUploadDownPayment?: any;

  acceptSalesOfferMutation?: any;
  mutationAcceptSalesOffer?: any;

  formatPrice: (price: string, currency?: string) => string;
  stages: any[];
  getStatusIcon: (status: string) => React.ReactNode;
  getStatusBadge: (status: string) => React.ReactNode;
  isApproving: boolean;
  isRejecting: boolean;
  isSalesOfferUploading: boolean;
  isDownPaymentApproving: boolean;
  isSPAUploading: boolean;
  isDownPaymentUploading?: boolean;
}

export function normalizeBookingDetails(data: any): BookingDetailsResponse {
  if (!data) {
    return {
      reservation: {
        reservation_id: 0,
        reservation_status_type: "identification",
        reservation_status: "in_process",
      },
      media: {},
      user: {},
      paymentPlan: {},
      payment_plan: {},
      country: { name: "UAE", currency: "AED" },
      property: {},
      project: {},
      developer: {},
    };
  }

   let root = data;
  if (root?.data && typeof root.data === "object" && !Array.isArray(root.data)) {
    if (
      root.data.reservation ||
      root.data.items ||
      root.data.user ||
      root.data.property ||
      root.data.id ||
      root.data.reservation_id
    ) {
      root = root.data;
    }
  }

   if (Array.isArray(root?.items) && root.items.length > 0) {
    root = root.items[0];
  } else if (Array.isArray(root) && root.length > 0) {
    root = root[0];
  }

  const rawReservation = root?.reservation || root;
  const innerReservation =
    rawReservation?.reservation && typeof rawReservation.reservation === "object"
      ? rawReservation.reservation
      : rawReservation;

  const reservation =
    innerReservation?.reservation_id ||
      innerReservation?.id ||
      innerReservation?.reservation_status ||
      innerReservation?.reservation_status_type
      ? innerReservation
      : rawReservation;

  const rawMedia =
    root?.media ||
    rawReservation?.media ||
    innerReservation?.media ||
    reservation?.media ||
    {};

  const media = {
    ...rawMedia,
    identification:
      rawMedia?.identification ||
      reservation?.identification ||
      rawReservation?.identification ||
      root?.identification ||
      null,
    selfie:
      rawMedia?.selfie ||
      reservation?.selfie ||
      rawReservation?.selfie ||
      root?.selfie ||
      null,
    sales_offer:
      rawMedia?.sales_offer ||
      reservation?.sales_offer ||
      rawReservation?.sales_offer ||
      root?.sales_offer ||
      null,
    down_payment:
      rawMedia?.down_payment ||
      reservation?.down_payment ||
      rawReservation?.down_payment ||
      root?.down_payment ||
      null,
    sales_purchase:
      rawMedia?.sales_purchase ||
      reservation?.sales_purchase ||
      rawReservation?.sales_purchase ||
      root?.sales_purchase ||
      null,
  };

  const user =
    root?.user ||
    rawReservation?.user ||
    innerReservation?.user ||
    root?.client ||
    reservation?.user ||
    reservation?.client ||
    {};

  const property =
    root?.property ||
    rawReservation?.property ||
    innerReservation?.property ||
    reservation?.property ||
    {};

  const project =
    property?.project ||
    root?.project ||
    rawReservation?.project ||
    innerReservation?.project ||
    reservation?.project ||
    {};

  const developer =
    project?.developer ||
    root?.developer ||
    rawReservation?.developer ||
    innerReservation?.developer ||
    reservation?.developer ||
    {};

  const country =
    project?.country ||
    root?.country ||
    rawReservation?.country ||
    innerReservation?.country ||
    reservation?.country ||
    { name: "UAE", currency: "AED" };

  const paymentPlan =
    root?.payment_plan ||
    root?.paymentPlan ||
    rawReservation?.payment_plan ||
    rawReservation?.paymentPlan ||
    innerReservation?.payment_plan ||
    innerReservation?.paymentPlan ||
    reservation?.payment_plan ||
    reservation?.paymentPlan ||
    {};

  const resId =
    innerReservation?.reservation_id ||
    innerReservation?.id ||
    rawReservation?.reservation_id ||
    rawReservation?.id ||
    root?.reservation_id ||
    root?.id ||
    0;

  const statusType =
    innerReservation?.reservation_status_type ||
    innerReservation?.status_type ||
    rawReservation?.reservation_status_type ||
    rawReservation?.status_type ||
    root?.reservation_status_type ||
    root?.status_type ||
    "identification";

  const status =
    innerReservation?.reservation_status ||
    innerReservation?.status ||
    rawReservation?.reservation_status ||
    rawReservation?.status ||
    root?.reservation_status ||
    root?.status ||
    "in_process";

  const normalizedReservation = {
    ...reservation,
    reservation_id: resId,
    id: resId,
    reservation_status_type: statusType,
    status_type: statusType,
    reservation_status: status,
    status: status,
    reservation_date:
      reservation?.reservation_date ||
      root?.reservation_date ||
      reservation?.created_at ||
      root?.created_at ||
      reservation?.updated_at ||
      root?.updated_at,
    expiry_date:
      reservation?.expiry_date ||
      root?.expiry_date,
    comments:
      reservation?.comments ||
      root?.comments,
    price:
      reservation?.price ||
      root?.price ||
      property?.price,
    currency:
      reservation?.currency ||
      root?.currency ||
      country?.currency ||
      "AED",
    reservation_fee:
      reservation?.reservation_fee ||
      root?.reservation_fee,
    service_fee:
      reservation?.service_fee ||
      root?.service_fee,
  };

  return {
    ...root,
    reservation: normalizedReservation,
    media,
    user,
    paymentPlan,
    payment_plan: paymentPlan,
    property: {
      ...property,
      project: {
        ...project,
        developer,
        country,
      },
    },
    project,
    developer,
    country,
  };
}

export default function useBookingDetails({
  reservationId,
}: UseBookingDetailsParams): UseBookingDetailsReturn {
  const queryClient = useQueryClient();
  const { t } = useLanguage();
  const router = useRouter();

  const {
    data: bookingData,
    isLoading,
    isError,
    error,
    refetch,
  } = useQuery<BookingDetailsResponse>({
    queryKey: ["reservation", reservationId],
    queryFn: async () => {
      const res: any =
        await DashboardAdminService.getBookingDetails(reservationId);

      return normalizeBookingDetails(res);
    },
    enabled: !!reservationId,
    retry: false,
    refetchInterval: 5000,
  });

  const approveMutation = useMutation<any, unknown, any>({
    mutationFn: async (variables: any) => {
      const comments = typeof variables === "string" ? variables : variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const resType = (variables?.reservation_status_type || variables?.type || "IDENTIFICATION").toUpperCase();
      const body: Record<string, unknown> = {
        reservation_id: targetId,
        status: "confirmed",
        reservation_status_type: resType,
      };
      if (comments) body.comments = comments;
      return DashboardAdminService.confirmBooking(targetId, body);
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = Number(variables?.reservationId) || Number(reservationId);
      if (typeof window !== "undefined" && targetId) {
        localStorage.setItem(`approved_stage1_${targetId}`, "true");
      }
      const updateCache = (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status = "confirmed";
        res.status = "confirmed";
        res.reservation_status_type = "identification";
        res.status_type = "identification";
        if (typeof variables === "string" && variables) {
          res.comments = variables;
        } else if (variables?.comments) {
          res.comments = variables.comments;
        }
        return {
          ...old,
          reservation: res,
        };
      };
      queryClient.setQueryData(["reservation", targetId], updateCache);
      if (reservationId && targetId !== Number(reservationId)) {
        queryClient.setQueryData(["reservation", Number(reservationId)], updateCache);
      }
      queryClient.invalidateQueries({
        queryKey: ["reservation", targetId],
      });
      queryClient.invalidateQueries({
        queryKey: ["reservation", reservationId],
      });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardInProgressReservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartStatusMetrics"] });
      toast.success(t("reservations.messages.approveSuccess"));
    },
    onError: (error: any, variables: any) => {
      const errMsg = error?.response?.data?.message || error?.message || "";
      const targetId = Number(variables?.reservationId) || Number(reservationId);
      queryClient.invalidateQueries({ queryKey: ["reservation", targetId] });
      queryClient.invalidateQueries({ queryKey: ["reservation", reservationId] });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });

      if (errMsg.toLowerCase().includes("already approved")) {
        if (typeof window !== "undefined" && targetId) {
          localStorage.setItem(`approved_stage1_${targetId}`, "true");
        }
        toast.info(t("reservations.messages.alreadyApproved"));
        return;
      }
      console.error("Approve reservation error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.approveFailed"));
      toast.error(msg);
    },
  });
  const declineMutation = useMutation<any, unknown, any>({
    mutationFn: async (variables: any) => {
      const comments = typeof variables === "string" ? variables : variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const resType = (variables?.reservation_status_type || variables?.type || "IDENTIFICATION").toUpperCase();
      const payload: Record<string, string> = {
        status: "cancelled",
        reservation_status_type: resType,
      };
      if (comments) payload.comments = comments;
      return DashboardAdminService.declineBooking(targetId, payload as any);
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = Number(variables?.reservationId) || Number(reservationId);
      if (typeof window !== "undefined" && targetId) {
        localStorage.removeItem(`approved_stage1_${targetId}`);
      }
      queryClient.invalidateQueries({
        queryKey: ["reservation", reservationId],
      });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardInProgressReservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartStatusMetrics"] });
      toast.success(t("reservations.messages.declineSuccess"));
      router.push("/admin/reservations");
    },
    onError: (error: any) => {
      console.error("Decline reservation error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.declineFailed"));
      toast.error(msg);
    },
  });

  const uploadSalesOfferMutation = useMutation<
    ApiResponse<unknown>,
    unknown,
    any
  >({
    mutationFn: async (variables: any) => {
      const file = variables?.file;
      const comments = variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const formData = new FormData();
      formData.append("reservation_id", String(targetId));
      if (file) {
        formData.append("file", file);
        formData.append("sales_offer", file);
      }
      if (comments) formData.append("comments", comments);
      return DashboardAdminService.uploadSalesOffer(formData) as Promise<
        ApiResponse<unknown>
      >;
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = variables?.reservationId || reservationId;
      queryClient.setQueryData(["reservation", targetId], (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status_type = "sales_offer";
        res.status_type = "sales_offer";
        res.reservation_status = "in_process";
        res.status = "in_process";
        const media = old.media ? { ...old.media } : {};
        if (variables?.file) {
          media.sales_offer = URL.createObjectURL(variables.file);
        }
        return {
          ...old,
          reservation: res,
          media,
        };
      });
      queryClient.invalidateQueries({
        queryKey: ["reservation", targetId],
      });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardInProgressReservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartStatusMetrics"] });
      toast.success(t("reservations.messages.salesOfferSuccess"));
    },
    onError: (error: any) => {
      console.error("Upload Sales Offer error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.salesOfferFailed"));
      toast.error(msg);
    },
  });

  const approveDownPaymentMutation = useMutation<any, unknown, any>({
    mutationFn: async (variables: any) => {
      const comments = typeof variables === "string" ? variables : variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const resType = (variables?.reservation_status_type || variables?.type || "DOWN_PAYMENT").toUpperCase();
      const body: Record<string, unknown> = {
        reservation_id: targetId,
        status: "confirmed",
        reservation_status_type: resType,
      };
      if (comments) body.comments = comments;
      return DashboardAdminService.confirmBooking(targetId, body);
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = variables?.reservationId || reservationId;
      if (typeof window !== "undefined" && targetId) {
        const clean = String(targetId).replace(/\D/g, "");
        localStorage.setItem(`approved_down_payment_${targetId}`, "true");
        if (clean) localStorage.setItem(`approved_down_payment_${clean}`, "true");
      }
      queryClient.setQueryData(["reservation", targetId], (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status = "confirmed";
        res.status = "confirmed";
        return {
          ...old,
          reservation: res,
        };
      });
      queryClient.invalidateQueries({
        queryKey: ["reservation", targetId],
      });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardInProgressReservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartStatusMetrics"] });
      toast.success(t("reservations.messages.approveSuccess"));
    },
    onError: (error: any) => {
      console.error("Approve down payment error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.approveFailed"));
      toast.error(msg);
    },
  });

  const uploadDownPaymentMutation = useMutation<
    ApiResponse<unknown>,
    unknown,
    any
  >({
    mutationFn: async (variables: any) => {
      const file = variables?.file;
      const comments = variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const formData = new FormData();
      formData.append("reservation_id", String(targetId));
      if (file) {
        formData.append("file", file);
        formData.append("down_payment", file);
      }
      if (comments) formData.append("comments", comments);
      return DashboardAdminService.uploadDownPayment(formData) as Promise<
        ApiResponse<unknown>
      >;
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = variables?.reservationId || reservationId;
      if (typeof window !== "undefined" && targetId) {
        const clean = String(targetId).replace(/\D/g, "");
        localStorage.setItem(`uploaded_down_payment_${targetId}`, "true");
        if (clean) localStorage.setItem(`uploaded_down_payment_${clean}`, "true");
      }
      queryClient.setQueryData(["reservation", targetId], (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status_type = "down_payment";
        res.status_type = "down_payment";
        const media = old.media ? { ...old.media } : {};
        if (variables?.file) {
          media.down_payment = URL.createObjectURL(variables.file);
        }
        return {
          ...old,
          reservation: res,
          media,
        };
      });
      queryClient.invalidateQueries({ queryKey: ["reservation", targetId] });
      queryClient.invalidateQueries({ queryKey: ["reservation", reservationId] });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      toast.success(t("reservations.messages.paymentUploaded") || "Payment receipt uploaded successfully");
    },
    onError: (error: any) => {
      console.error("Upload down payment error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.paymentUploadFailed") || "Failed to upload payment receipt");
      toast.error(msg);
    },
  });

  const acceptSalesOfferMutation = useMutation<any, unknown, any>({
    mutationFn: async (variables: any) => {
      const comments = typeof variables === "string" ? variables : variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const body: Record<string, unknown> = {
        reservation_id: targetId,
        status: "confirmed",
        reservation_status_type: "SALES_OFFER",
      };
      if (comments) body.comments = comments;
      return DashboardAdminService.confirmBooking(targetId, body);
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = variables?.reservationId || reservationId;
      if (typeof window !== "undefined" && targetId) {
        const clean = String(targetId).replace(/\D/g, "");
        localStorage.setItem(`accepted_sales_offer_${targetId}`, "true");
        if (clean) localStorage.setItem(`accepted_sales_offer_${clean}`, "true");
        localStorage.setItem(`approved_stage1_${targetId}`, "true");
        if (clean) localStorage.setItem(`approved_stage1_${clean}`, "true");
      }
      queryClient.setQueryData(["reservation", targetId], (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status_type = "sales_offer";
        res.status_type = "sales_offer";
        res.reservation_status = "confirmed";
        res.status = "confirmed";
        return {
          ...old,
          reservation: res,
        };
      });
      queryClient.invalidateQueries({ queryKey: ["reservation", targetId] });
      queryClient.invalidateQueries({ queryKey: ["reservation", reservationId] });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      toast.success(t("reservations.messages.salesOfferAccepted") || "Sales offer accepted! Proceed to down payment");
    },
    onError: (error: any) => {
      console.error("Accept sales offer error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, "Failed to confirm sales offer");
      toast.error(msg);
    },
  });

  const uploadSPAMutation = useMutation<
    ApiResponse<unknown>,
    unknown,
    any
  >({
    mutationFn: async (variables: any) => {
      const file = variables?.file;
      const comments = variables?.comments || "";
      const targetId = variables?.reservationId || reservationId;
      const formData = new FormData();
      formData.append("reservation_id", String(targetId));
      if (file) formData.append("file", file);
      if (comments) formData.append("comments", comments);
      return DashboardAdminService.uploadSPA(targetId, formData) as Promise<
        ApiResponse<unknown>
      >;
    },
    onSuccess: (_data: any, variables: any) => {
      const targetId = variables?.reservationId || reservationId;
      queryClient.setQueryData(["reservation", targetId], (old: any) => {
        if (!old) return old;
        const res = old.reservation ? { ...old.reservation } : { ...old };
        res.reservation_status_type = "sales_purchase";
        res.status_type = "sales_purchase";
        res.reservation_status = "confirmed";
        res.status = "confirmed";
        const media = old.media ? { ...old.media } : {};
        if (variables?.file) {
          media.sales_purchase = URL.createObjectURL(variables.file);
        }
        return {
          ...old,
          reservation: res,
          media,
        };
      });
      queryClient.invalidateQueries({
        queryKey: ["reservation", reservationId],
      });
      queryClient.invalidateQueries({ queryKey: ["bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "reservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardInProgressReservations"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartCounts"] });
      queryClient.invalidateQueries({ queryKey: ["dashboardChartStatusMetrics"] });
      toast.success(t("reservations.messages.spaSuccess"));
    },
    onError: (error: any) => {
      console.error("Upload SPA error details:", error?.response?.data || error);
      const msg = getErrorMessage(error, t("reservations.messages.spaFailed"));
      toast.error(msg);
    },
  });

  const currencyMap: Record<string, string> = {
    Dollar: "USD",
    Euro: "EUR",
    Pound: "GBP",
    EGP: "EGP",
    AED: "AED",
  };

  const formatPrice = (price: string, currency: string = "AED") => {
    const isoCode = currencyMap[currency] || currency || "AED";
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: isoCode,
    }).format(Number(price) || 0);
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "Complete":
        return <CheckCircle className="h-5 w-5 text-green-600" />;
      case "Rejected":
        return <XCircle className="h-5 w-5 text-red-600" />;
      case "Pending":
        return <Clock className="h-5 w-5 text-orange-600" />;
      default:
        return <Clock className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const styles: Record<string, string> = {
      Complete: "bg-green-50 text-green-700 border-green-200",
      Rejected: "bg-red-50 text-red-700 border-red-200",
      Pending: "bg-orange-50 text-orange-700 border-orange-200",
      Waiting: "bg-gray-50 text-gray-700 border-gray-200",
    };
    const labelKey: Record<string, string> = {
      Complete: "reservations.statusMap.completed",
      Rejected: "reservations.statusMap.cancelled",
      Pending: "reservations.statusMap.pending",
      Waiting: "reservations.details.waiting",
    };
    const label = labelKey[status] ? t(labelKey[status]) : status;
    return (
      <Badge className={`${styles[status] || styles.Waiting} text-xs`}>
        {label}
      </Badge>
    );
  };

  const getStageStatus = (
    stageId: number,
    currentStatusType?: string,
    currentStatus?: string,
    mediaObj?: any,
  ): "Complete" | "Rejected" | "Pending" | "Waiting" => {
    const rawType = (currentStatusType || "").toLowerCase().trim();
    const normType = rawType.replace(/\s+/g, "_");
    const status = (currentStatus || "").toLowerCase().trim().replace(/\s+/g, "_");
    const isCancelled = status === "cancelled" || status === "rejected" || status === "declined" || status === "expired";
    const isConfirmed = status === "confirmed" || status === "approved" || status === "complete" || status === "completed";
    const isInProcess = !isConfirmed && !isCancelled;
    const isStage1Type = normType === "identification" || normType === "identification_confirmation";
    const isStage2Type = normType === "sales_offer" || normType === "sales_offer_request" || normType === "sales_offer_approval";
     const isStage2UploadPending = normType === "sales_offer_request";
    const isStage2ApprovalType = normType === "sales_offer" || normType === "sales_offer_approval";
    const isStage3Type = normType === "down_payment" || normType === "down_payment_pending";
    const isStage4Type = normType === "sales_purchase" || normType === "spa" || normType === "sales_purchase_agreement";
    const hasSalesOfferDoc = Boolean(mediaObj?.sales_offer);
    const hasDownPaymentDoc = Boolean(mediaObj?.down_payment);
    const hasSpaDoc = Boolean(mediaObj?.sales_purchase);

    const cleanResId = reservationId ? String(reservationId).replace(/\D/g, "") : "";

    const isStage1SavedApproved =
      typeof window !== "undefined"
        ? (Boolean(reservationId) && localStorage.getItem(`approved_stage1_${reservationId}`) === "true") ||
          (Boolean(cleanResId) && localStorage.getItem(`approved_stage1_${cleanResId}`) === "true") ||
          (Boolean(reservationId) && localStorage.getItem(`reservation_${reservationId}_stage1_approved`) === "true") ||
          (Boolean(cleanResId) && localStorage.getItem(`reservation_${cleanResId}_stage1_approved`) === "true")
        : false;

    const isSalesOfferAccepted =
      typeof window !== "undefined"
        ? (Boolean(reservationId) && localStorage.getItem(`accepted_sales_offer_${reservationId}`) === "true") ||
          (Boolean(cleanResId) && localStorage.getItem(`accepted_sales_offer_${cleanResId}`) === "true")
        : false;

    const isDownPaymentApproved =
      typeof window !== "undefined"
        ? (Boolean(reservationId) && localStorage.getItem(`approved_down_payment_${reservationId}`) === "true") ||
          (Boolean(cleanResId) && localStorage.getItem(`approved_down_payment_${cleanResId}`) === "true")
        : false;

     const isStage1Complete =
      !(isStage1Type && isInProcess) &&
      (isStage1SavedApproved ||
        (isStage1Type && isConfirmed) ||
        isStage2Type ||
        isStage3Type ||
        isStage4Type ||
        hasSalesOfferDoc ||
        hasDownPaymentDoc ||
        hasSpaDoc ||
        isSalesOfferAccepted);

    if (stageId === 1) {
      if (isStage1Complete) return "Complete";
      if (isCancelled) return "Rejected";
      return "Pending";
    }

     const isStage2Complete =
      isStage1Complete &&
      !isStage2UploadPending &&
      !(isStage2ApprovalType && isInProcess) &&
      ((isStage2ApprovalType && isConfirmed) ||
        isSalesOfferAccepted ||
        isStage3Type ||
        isStage4Type ||
        hasDownPaymentDoc ||
        hasSpaDoc);

    // Stage 2 pending when: stage 1 is complete and stage 2 is not yet complete
    const isStage2Pending =
      isStage1Complete &&
      !isCancelled &&
      !isStage2Complete;

    if (stageId === 2) {
      if (!isStage1Complete) return "Waiting";
      if (isStage2Complete) return "Complete";
      if (isCancelled) return "Rejected";
      if (isStage2Pending || hasSalesOfferDoc) return "Pending";
      return "Waiting";
    }

     const isStage3Complete =
      isStage2Complete &&
      !(isStage3Type && isInProcess) &&
      ((isStage3Type && isConfirmed) || isDownPaymentApproved || isStage4Type || hasSpaDoc);

     const isStage3Pending =
      isStage2Complete &&
      !isCancelled &&
      !isStage3Complete;

    if (stageId === 3) {
      if (!isStage2Complete) return "Waiting";
      if (isStage3Complete) return "Complete";
      if (isCancelled) return "Rejected";
      if (isStage3Pending || hasDownPaymentDoc) return "Pending";
      return "Waiting";
    }

     if (stageId === 4) {
      if (!isStage3Complete) return "Waiting";
      if (hasSpaDoc || (isStage4Type && isConfirmed)) return "Complete";
      if (isCancelled) return "Rejected";
      return "Pending";
    }
    return "Waiting";
  };

  const getStages = () => {
    if (!bookingData) return [];

    const resObj =
      bookingData.reservation ||
      (bookingData as any)?.data?.reservation ||
      (bookingData as any)?.data ||
      bookingData ||
      {};

    const mediaObj =
      bookingData.media ||
      (bookingData as any)?.data?.media ||
      resObj?.media ||
      {};

    const userObj =
      bookingData.user ||
      (bookingData as any)?.data?.user ||
      resObj?.user ||
      (bookingData as any)?.client ||
      {};

    const statusType =
      resObj?.reservation_status_type ||
      resObj?.status_type ||
      (bookingData as any)?.status_type ||
      (bookingData as any)?.reservation_status_type ||
      "identification";

    const status =
      resObj?.reservation_status ||
      resObj?.status ||
      (bookingData as any)?.status ||
      (bookingData as any)?.reservation_status ||
      "in_process";

    const comments = resObj?.comments || (bookingData as any)?.comments;
    const authorName =
      [userObj?.first_name, userObj?.last_name].filter(Boolean).join(" ") ||
      userObj?.user_name ||
      userObj?.name ||
      "Client";
    const date =
      resObj?.reservation_date ||
      resObj?.created_at ||
      (bookingData as any)?.reservation_date;

     const normType = statusType.toLowerCase().trim().replace(/\s+/g, "_");
    const normStatus = status.toLowerCase().trim().replace(/\s+/g, "_");

    return [
      {
        id: 1,
        name: t("reservations.typeMap.identification"),
        status: getStageStatus(1, statusType, status, mediaObj),
        step: t("reservations.details.stepOf", { step: 1, total: 4 }),
        currentStatusType: normType,
        currentStatus: normStatus,
        subtitle: t("reservations.stages.identificationSubtitle"),
        documents: [
          mediaObj?.identification
            ? { name: t("reservations.typeMap.identification"), url: mediaObj.identification }
            : null,
          mediaObj?.selfie
            ? { name: t("reservations.details.selfie"), url: mediaObj.selfie }
            : null,
        ].filter(Boolean) as Array<{ name: string; url: string }>,
        comments: comments
          ? [
            {
              author: authorName,
              date: date,
              text: comments,
            },
          ]
          : [],
      },
      {
        id: 2,
        name: t("reservations.typeMap.sales_offer"),
        status: getStageStatus(2, statusType, status, mediaObj),
        step: t("reservations.details.stepOf", { step: 2, total: 4 }),
        currentStatusType: normType,
        currentStatus: normStatus,
        reservationId: Number(reservationId),
        subtitle:
          !mediaObj?.sales_offer
            ? t("reservations.stages.salesOfferUploadSubtitle")
            : normType.includes("sales_offer") && normStatus === "confirmed"
              ? t("reservations.stages.salesOfferApprovedSubtitle")
              : t("reservations.stages.salesOfferAwaitingSubtitle"),
        documents: mediaObj?.sales_offer
          ? [{ name: t("reservations.typeMap.sales_offer"), url: mediaObj.sales_offer }]
          : [],
      },
      {
        id: 3,
        name: t("reservations.typeMap.down_payment"),
        status: getStageStatus(3, statusType, status, mediaObj),
        step: t("reservations.details.stepOf", { step: 3, total: 4 }),
        currentStatusType: normType,
        currentStatus: normStatus,
        subtitle:
          normType.includes("sales_offer") && normStatus === "confirmed"
            ? t("reservations.stages.downPaymentAwaitingSubtitle")
            : normType.includes("down_payment") && normStatus === "in_process"
              ? t("reservations.stages.downPaymentReviewSubtitle")
              : normType.includes("down_payment") && normStatus === "confirmed"
                ? t("reservations.stages.downPaymentApprovedSubtitle")
                : t("reservations.typeMap.down_payment"),
        documents: mediaObj?.down_payment
          ? [
            {
              name: t("reservations.details.downPaymentReceipt"),
              url: mediaObj.down_payment,
            },
          ]
          : [],
      },
      {
        id: 4,
        name: t("reservations.typeMap.sales_purchase"),
        status: getStageStatus(4, statusType, status, mediaObj),
        step: t("reservations.details.stepOf", { step: 4, total: 4 }),
        currentStatusType: normType,
        currentStatus: normStatus,
        subtitle: t("reservations.stages.spaSubtitle"),
        documents: mediaObj?.sales_purchase
          ? [{ name: t("reservations.details.spaDocument"), url: mediaObj.sales_purchase }]
          : [],
      },
    ];
  };

  const stages = getStages();

  return {
    bookingData,
    reservationData: bookingData,
    isLoading,
    isError,
    error,
    refetch,
    approveMutation,
    mutationApprove: approveMutation,
    declineMutation,
    mutationDecline: declineMutation,
    uploadSalesOfferMutation,
    mutationSalesOffer: uploadSalesOfferMutation,
    uploadSPAMutation,
    mutationSPA: uploadSPAMutation,
    approveDownPaymentMutation,
    mutationDownPayment: approveDownPaymentMutation,
    uploadDownPaymentMutation,
    mutationUploadDownPayment: uploadDownPaymentMutation,
    acceptSalesOfferMutation,
    mutationAcceptSalesOffer: acceptSalesOfferMutation,
    formatPrice,
    stages,
    getStatusIcon,
    getStatusBadge,
    isApproving: approveMutation.isPending,
    isRejecting: declineMutation.isPending,
    isSalesOfferUploading: uploadSalesOfferMutation.isPending,
    isDownPaymentApproving: approveDownPaymentMutation.isPending,
    isSPAUploading: uploadSPAMutation.isPending,
    isDownPaymentUploading: uploadDownPaymentMutation.isPending,
  };
}