import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Check, Clock, Download, File, FileText, Loader2, Upload, X, ChevronDown, ChevronUp, Image as ImageIcon } from "lucide-react";
import React, { useState, useEffect } from "react";
import { useLanguage } from "@/contexts/LanguageContext";
import { toast } from "sonner";

interface BookingStagesTimelineProps {
  stages: any[];
  getStatusBadge: (status: string) => React.ReactNode;
  handleDownload: (url: string, filename: string) => void;
  salesOfferFile: File | null;
  setSalesOfferFile: (file: File | null) => void;
  spaFile: File | null;
  setSpaFile: (file: File | null) => void;
  adminComment: string;
  setAdminComment: (comment: string) => void;
  uploadSalesOfferMutation: any;
  uploadSPAMutation: any;
  approveMutation: any;
  declineMutation: any;
  approveDownPaymentMutation: any;
  handleSalesOfferUpload: () => void;
  handleSpaUpload: () => void;
  reservationId?: number | string;
  uploadDownPaymentMutation?: any;
  acceptSalesOfferMutation?: any;
}

export function BookingStagesTimeline({
  stages,
  getStatusBadge,
  handleDownload,
  salesOfferFile,
  setSalesOfferFile,
  spaFile,
  setSpaFile,
  adminComment,
  setAdminComment,
  uploadSalesOfferMutation,
  uploadSPAMutation,
  approveMutation,
  declineMutation,
  approveDownPaymentMutation,
  handleSalesOfferUpload,
  handleSpaUpload,
  reservationId,
  uploadDownPaymentMutation,
  acceptSalesOfferMutation,
}: BookingStagesTimelineProps) {
  const { t, language } = useLanguage();
  const isAr = language === "ar";

  const [isReuploadingSalesOffer, setIsReuploadingSalesOffer] = useState(false);
  const [salesOfferImagePreview, setSalesOfferImagePreview] = useState<string | null>(null);

   const [downPaymentFile, setDownPaymentFile] = useState<File | null>(null);
  const [downPaymentPreview, setDownPaymentPreview] = useState<string | null>(null);
  const [downPaymentComment, setDownPaymentComment] = useState("");
  const [isReuploadingDownPayment, setIsReuploadingDownPayment] = useState(false);

  useEffect(() => {
    if (salesOfferFile && salesOfferFile.type.startsWith("image/")) {
      const url = URL.createObjectURL(salesOfferFile);
      setSalesOfferImagePreview(url);
      return () => URL.revokeObjectURL(url);
    } else {
      setSalesOfferImagePreview(null);
    }
  }, [salesOfferFile]);

  useEffect(() => {
    if (downPaymentFile && downPaymentFile.type.startsWith("image/")) {
      const url = URL.createObjectURL(downPaymentFile);
      setDownPaymentPreview(url);
      return () => URL.revokeObjectURL(url);
    } else {
      setDownPaymentPreview(null);
    }
  }, [downPaymentFile]);

   const stage1FromServer = stages.find((s: any) => s.id === 1);
  const stage2FromServer = stages.find((s: any) => s.id === 2);
  const stage3FromServer = stages.find((s: any) => s.id === 3);
  const targetResId = reservationId || stages?.[0]?.reservationId || (stages as any)?.reservationId;
  const cleanTargetId = targetResId ? String(targetResId).replace(/\D/g, "") : "";

  const isSavedInStorage = (id: any) => {
    if (typeof window === "undefined" || !id) return false;
    const clean = String(id).replace(/\D/g, "");
    return (
      localStorage.getItem(`approved_stage1_${id}`) === "true" ||
      (Boolean(clean) && localStorage.getItem(`approved_stage1_${clean}`) === "true") ||
      localStorage.getItem(`reservation_${id}_stage1_approved`) === "true" ||
      (Boolean(clean) && localStorage.getItem(`reservation_${clean}_stage1_approved`) === "true")
    );
  };

  const isSalesOfferAcceptedInStorage = (id: any) => {
    if (typeof window === "undefined" || !id) return false;
    const clean = String(id).replace(/\D/g, "");
    return (
      localStorage.getItem(`accepted_sales_offer_${id}`) === "true" ||
      (Boolean(clean) && localStorage.getItem(`accepted_sales_offer_${clean}`) === "true")
    );
  };

  const isDownPaymentApprovedInStorage = (id: any) => {
    if (typeof window === "undefined" || !id) return false;
    const clean = String(id).replace(/\D/g, "");
    return (
      localStorage.getItem(`approved_down_payment_${id}`) === "true" ||
      (Boolean(clean) && localStorage.getItem(`approved_down_payment_${clean}`) === "true")
    );
  };

  const isStage1SavedInStorage =
    isSavedInStorage(targetResId) || (reservationId && isSavedInStorage(reservationId));

  const isLaterStageActiveOrDone =
    stages.some((s: any) => s.id > 1 && (s.status === "Complete" || (s.documents && s.documents.length > 0))) ||
    stage1FromServer?.currentStatusType === "sales_offer" ||
    stage1FromServer?.currentStatusType === "down_payment" ||
    stage1FromServer?.currentStatusType === "sales_purchase";

  const stage1InitiallyApproved =
    Boolean(isStage1SavedInStorage) ||
    Boolean(isLaterStageActiveOrDone) ||
    stage1FromServer?.status === "Complete" ||
    stage1FromServer?.currentStatus === "confirmed" ||
    stage1FromServer?.currentStatus === "approved" ||
    stage1FromServer?.currentStatus === "completed" ||
    (stage1FromServer?.currentStatusType !== "identification" && stage1FromServer?.currentStatusType !== "identification_confirmation");

  const [isStage1Approved, setIsStage1Approved] = useState(Boolean(stage1InitiallyApproved));
  const [collapsedStages, setCollapsedStages] = useState<Record<number, boolean>>({});

   useEffect(() => {
    if (stage1InitiallyApproved && !isStage1Approved) {
      setIsStage1Approved(true);
    }
    if (isSavedInStorage(targetResId) && !isStage1Approved) {
      setIsStage1Approved(true);
    }
  }, [stage1InitiallyApproved, targetResId]);

  const isCollapsed = (stageId: number, isComplete: boolean, isPending: boolean): boolean => {
    if (collapsedStages[stageId] !== undefined) {
      return collapsedStages[stageId];
    }
     if (isComplete) return true;
    if (isPending) return false;
    return false;
  };

  const toggleStage = (stageId: number, isComplete: boolean, isPending: boolean) => {
    setCollapsedStages((prev) => ({
      ...prev,
      [stageId]: !isCollapsed(stageId, isComplete, isPending),
    }));
  };

  const handleApprove = () => {
    approveMutation.mutate(
      {
        comments: adminComment,
        reservation_status_type: "IDENTIFICATION",
        reservationId: targetResId,
      },
      {
        onSuccess: () => {
          setIsStage1Approved(true);
          if (typeof window !== "undefined" && targetResId) {
            localStorage.setItem(`approved_stage1_${targetResId}`, "true");
            if (cleanTargetId) localStorage.setItem(`approved_stage1_${cleanTargetId}`, "true");
            localStorage.setItem(`reservation_${targetResId}_stage1_approved`, "true");
            if (cleanTargetId) localStorage.setItem(`reservation_${cleanTargetId}_stage1_approved`, "true");
          }
          setAdminComment("");
           setCollapsedStages((prev) => ({ ...prev, 1: true, 2: false }));
          setTimeout(() => {
            const stage2El = document.getElementById("stage-2");
            if (stage2El) {
              stage2El.scrollIntoView({ behavior: "smooth", block: "center" });
            }
          }, 200);
        },
        onError: (err: any) => {
          const errMsg = err?.response?.data?.message || err?.message || "";
          if (errMsg.toLowerCase().includes("already approved")) {
            setIsStage1Approved(true);
            if (typeof window !== "undefined" && targetResId) {
              localStorage.setItem(`approved_stage1_${targetResId}`, "true");
              if (cleanTargetId) localStorage.setItem(`approved_stage1_${cleanTargetId}`, "true");
            }
            setAdminComment("");
          }
        },
      }
    );
  };

  const handleAcceptSalesOffer = () => {
    if (acceptSalesOfferMutation) {
      acceptSalesOfferMutation.mutate(
        {
          reservationId: targetResId,
          comments: adminComment,
        },
        {
          onSuccess: () => {
            if (typeof window !== "undefined" && targetResId) {
              localStorage.setItem(`accepted_sales_offer_${targetResId}`, "true");
              if (cleanTargetId) localStorage.setItem(`accepted_sales_offer_${cleanTargetId}`, "true");
              localStorage.setItem(`approved_stage1_${targetResId}`, "true");
              if (cleanTargetId) localStorage.setItem(`approved_stage1_${cleanTargetId}`, "true");
            }
            setCollapsedStages((prev) => ({ ...prev, 2: true, 3: false }));
            setTimeout(() => {
              const stage3El = document.getElementById("stage-3");
              if (stage3El) {
                stage3El.scrollIntoView({ behavior: "smooth", block: "center" });
              }
            }, 200);
          },
        }
      );
    } else {
      if (typeof window !== "undefined" && targetResId) {
        localStorage.setItem(`accepted_sales_offer_${targetResId}`, "true");
        if (cleanTargetId) localStorage.setItem(`accepted_sales_offer_${cleanTargetId}`, "true");
      }
      setCollapsedStages((prev) => ({ ...prev, 2: true, 3: false }));
    }
  };

  const handleDownPaymentUpload = () => {
    if (!downPaymentFile) return;
    if (uploadDownPaymentMutation) {
      uploadDownPaymentMutation.mutate(
        {
          file: downPaymentFile,
          comments: downPaymentComment,
          reservationId: targetResId,
        },
        {
          onSuccess: () => {
            setDownPaymentFile(null);
            setDownPaymentComment("");
            setIsReuploadingDownPayment(false);
          },
        }
      );
    } else {
      setDownPaymentFile(null);
      setIsReuploadingDownPayment(false);
    }
  };

  const handleApproveDownPaymentAction = () => {
    approveDownPaymentMutation.mutate(
      {
        comments: adminComment || downPaymentComment,
        reservation_status_type: "DOWN_PAYMENT",
        reservationId: targetResId,
      },
      {
        onSuccess: () => {
          if (typeof window !== "undefined" && targetResId) {
            localStorage.setItem(`approved_down_payment_${targetResId}`, "true");
            if (cleanTargetId) localStorage.setItem(`approved_down_payment_${cleanTargetId}`, "true");
          }
          setCollapsedStages((prev) => ({ ...prev, 3: true, 4: false }));
          setTimeout(() => {
            const stage4El = document.getElementById("stage-4");
            if (stage4El) {
              stage4El.scrollIntoView({ behavior: "smooth", block: "center" });
            }
          }, 200);
        },
      }
    );
  };

  return (
    <div className="lg:col-span-2 space-y-4">
      {(() => {
         const s1 = stage1FromServer;
        const s2 = stage2FromServer;
        const s3 = stage3FromServer;

        const globalStage1Complete = Boolean(
          s1 &&
          (s1.status === "Complete" ||
            isStage1Approved ||
            stage1InitiallyApproved ||
            isStage1SavedInStorage ||
            s1.currentStatus === "confirmed" ||
            s1.currentStatus === "approved" ||
            (s1.currentStatusType !== "identification" && s1.currentStatusType !== "identification_confirmation") ||
            stages.some((sx: any) => sx.id > 1 && (sx.status === "Complete" || (sx.documents && sx.documents.length > 0))))
        );

        const globalStage2Complete = Boolean(
          globalStage1Complete &&
          s2 &&
          (s2.status === "Complete" ||
            isSalesOfferAcceptedInStorage(targetResId) ||
            (reservationId && isSalesOfferAcceptedInStorage(reservationId)) ||
            ((s2.currentStatusType === "sales_offer" || s2.currentStatusType === "sales_offer_approval") &&
              (s2.currentStatus === "confirmed" || s2.currentStatus === "approved" || s2.currentStatus === "completed")) ||
            s2.currentStatusType === "down_payment" ||
            s2.currentStatusType === "down_payment_pending" ||
            s2.currentStatusType === "sales_purchase" ||
            s2.currentStatusType === "sales_purchase_agreement" ||
            stages.some((sx: any) => sx.id > 2 && (sx.status === "Complete" || (sx.documents && sx.documents.length > 0))))
        );

        const globalStage3Complete = Boolean(
          globalStage2Complete &&
          s3 &&
          (s3.status === "Complete" ||
            isDownPaymentApprovedInStorage(targetResId) ||
            (reservationId && isDownPaymentApprovedInStorage(reservationId)) ||
            ((s3.currentStatusType === "down_payment" || s3.currentStatusType === "down_payment_pending") &&
              (s3.currentStatus === "confirmed" || s3.currentStatus === "approved" || s3.currentStatus === "completed")) ||
            s3.currentStatusType === "sales_purchase" ||
            s3.currentStatusType === "sales_purchase_agreement" ||
            stages.some((sx: any) => sx.id > 3 && (sx.status === "Complete" || (sx.documents && sx.documents.length > 0))))
        );

        const isCancelledGlobally = Boolean(s1 && (s1.currentStatus === "cancelled" || s1.currentStatus === "rejected"));

        return stages.map((stage: any) => {
          const isStage1Complete = stage.id === 1 ? globalStage1Complete : false;
          const isStage2Complete = stage.id === 2 ? globalStage2Complete : false;
          const isStage3Complete = stage.id === 3 ? globalStage3Complete : false;

          const isComplete =
            stage.id === 1
              ? globalStage1Complete
              : stage.id === 2
                ? globalStage2Complete
                : stage.id === 3
                  ? globalStage3Complete
                  : stage.status === "Complete";

          let isPending =
            stage.id === 1
              ? (!globalStage1Complete && stage.status === "Pending")
              : stage.id === 2
                ? (!globalStage2Complete && globalStage1Complete)
                : stage.id === 3
                  ? (!globalStage3Complete && globalStage2Complete)
                  : (globalStage3Complete && stage.status !== "Complete");

          // If the reservation is entirely cancelled, no stage should be active/pending.
          if (isCancelledGlobally) {
            isPending = false;
          }

          const isRejected = stage.status === "Rejected" || (isCancelledGlobally && !isComplete);
          const collapsed = isCollapsed(stage.id, isComplete, isPending);

        return (
          <div
            key={stage.id}
            id={`stage-${stage.id}`}
            className={`bg-white rounded-lg border overflow-hidden transition-all duration-200 ${isPending
                ? "border-teal-400 ring-2 ring-teal-500/20 shadow-xs"
                : isComplete
                  ? "border-emerald-200"
                  : isRejected
                    ? "border-rose-200"
                    : "border-gray-200 opacity-90"
              }`}
          >
            <div
              onClick={() => toggleStage(stage.id, isComplete, isPending)}
              className={`border-b p-4 flex items-center justify-between transition-colors cursor-pointer select-none ${isPending
                  ? "bg-teal-50/70 border-teal-200"
                  : isComplete
                    ? "bg-emerald-50/50 border-emerald-100"
                    : isRejected
                      ? "bg-rose-50/50 border-rose-100"
                      : "bg-gray-50/50 border-gray-200"
                }`}
            >
              <div className="flex items-center gap-3">
                <div
                  className={`w-9 h-9 rounded-full flex items-center justify-center font-semibold text-sm transition-colors ${isComplete
                      ? "bg-emerald-600 text-white shadow-xs"
                      : isPending
                        ? "bg-teal-600 text-white ring-4 ring-teal-100"
                        : isRejected
                          ? "bg-rose-600 text-white"
                          : "bg-gray-200 text-gray-500"
                    }`}
                >
                  {isComplete ? <Check className="h-4 w-4 stroke-[3]" /> : stage.id}
                </div>
                <div>
                  <h3 className="text-base font-semibold text-gray-900">
                    {t("reservations.details.stage")} {stage.id}: {stage.name}
                  </h3>
                  <p className="text-xs text-gray-500 mt-0.5">{stage.subtitle || stage.step}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {getStatusBadge(isComplete ? "Complete" : isPending ? "Pending" : stage.status)}
                {collapsed ? (
                  <ChevronDown className="h-4 w-4 text-gray-400" />
                ) : (
                  <ChevronUp className="h-4 w-4 text-gray-400" />
                )}
              </div>
            </div>

            {!collapsed && (
              <div className="p-5 space-y-4">
                {stage.id === 1 && isComplete && (
                  <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-800 text-xs font-medium rounded-lg border border-emerald-200">
                    <Check className="h-4 w-4 text-emerald-600 shrink-0" />
                    <span>{t("reservations.stages.stage1Closed")}</span>
                  </div>
                )}
                {stage.id === 2 && isComplete && (
                  <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-800 text-xs font-medium rounded-lg border border-emerald-200">
                    <Check className="h-4 w-4 text-emerald-600 shrink-0" />
                    <span>{t("reservations.stages.stage2Closed")}</span>
                  </div>
                )}

                {stage.id === 3 && isComplete && (
                  <div className="flex items-center gap-2 p-3 bg-emerald-50 text-emerald-800 text-xs font-medium rounded-lg border border-emerald-200">
                    <Check className="h-4 w-4 text-emerald-600 shrink-0" />
                    <span>{t("reservations.stages.stage3Closed")}</span>
                  </div>
                )}

                {(stage.documents && stage.documents.length > 0) ||
                  ((stage.id === 2 || stage.id === 3 || stage.id === 4) && isPending) ? (
                  <div>
                    <h4 className="text-sm font-semibold text-gray-900 mb-3">
                      {stage.documents && stage.documents.length > 0
                        ? `${t("reservations.details.documents")} (${stage.documents.length})`
                        : isPending
                          ? t("reservations.details.requiredAction")
                          : t("reservations.details.documents")}
                    </h4>
                    <div className="space-y-2">
                      {stage.documents &&
                        stage.documents.map((doc: any, idx: any) => {
                          const isImage = Boolean(
                            doc.url && (
                              doc.url.match(/\.(jpeg|jpg|png|webp|gif|svg)($|\?)/i) ||
                              doc.url.includes("image") ||
                              doc.url.startsWith("blob:") ||
                              doc.name?.match(/\.(jpeg|jpg|png|webp|gif)$/i)
                            )
                          );
                          return (
                            <div
                              key={idx}
                              className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200"
                            >
                              <div className="flex items-center gap-3 min-w-0">
                                {isImage ? (
                                  <div
                                    className="w-12 h-12 rounded-lg overflow-hidden border border-teal-200 shrink-0 bg-white flex items-center justify-center cursor-pointer hover:opacity-90 transition-opacity"
                                    onClick={() => window.open(doc.url, "_blank")}
                                    title={isAr ? "عرض الصورة" : "View image"}
                                  >
                                    <img src={doc.url} alt={doc.name} className="w-full h-full object-cover" />
                                  </div>
                                ) : (
                                  <div className="w-10 h-10 bg-teal-100 rounded-lg flex items-center justify-center shrink-0">
                                    <FileText className="h-5 w-5 text-teal-600" />
                                  </div>
                                )}
                                <div className="min-w-0">
                                  <span className="text-sm font-medium text-gray-900 block truncate">
                                    {doc.name}
                                  </span>
                                  {isImage && (
                                    <button
                                      type="button"
                                      onClick={() => window.open(doc.url, "_blank")}
                                      className="text-[11px] text-teal-600 hover:text-teal-700 hover:underline font-medium cursor-pointer"
                                    >
                                      {isAr ? "معاينة الصورة" : "View Image"}
                                    </button>
                                  )}
                                </div>
                              </div>
                              <Button
                                variant="ghost"
                                size="sm"
                                className="gap-2 text-teal-700 hover:text-teal-800 hover:bg-teal-50 shrink-0 cursor-pointer"
                                onClick={() => handleDownload(doc.url, doc.name)}
                              >
                                <Download className="h-4 w-4" />
                                {t("reservations.actions.download")}
                              </Button>
                            </div>
                          );
                        })}

                      {stage.id === 2 && isPending && (() => {
                        const hasDoc = stage.documents && stage.documents.length > 0;
                        const isUploadRequest = stage.currentStatusType === "sales_offer_request";
                         const isWaitingApproval =
                          stage.currentStatusType === "sales_offer" ||
                          stage.currentStatusType === "sales_offer_approval" ||
                          (hasDoc && !isUploadRequest);
                        const shouldShowUpload = isUploadRequest || (!hasDoc && !isWaitingApproval) || isReuploadingSalesOffer || Boolean(salesOfferFile);

                        if (shouldShowUpload) {
                          return (
                            <div className="mt-3 p-4 bg-teal-50/40 rounded-xl border border-teal-200 space-y-3">
                              <div className="flex items-center justify-between">
                                <div>
                                  <span className="text-xs font-bold uppercase tracking-wider text-teal-800 flex items-center gap-1.5">
                                    <ImageIcon className="h-4 w-4 text-teal-600" />
                                    {isAr ? "رفع صورة عرض المبيعات" : "Upload Sales Offer Image"}
                                  </span>
                                  <p className="text-xs text-gray-600 mt-0.5">
                                    {isAr
                                      ? "ارفع صورة عرض المبيعات (صورة واحدة فقط: PNG, JPG, WEBP). بعد الرفع، سينتظر النظام موافقة العميل."
                                      : "Upload the sales offer image (one image only: PNG, JPG, WEBP). Once uploaded, the system will wait for client approval."}
                                  </p>
                                </div>
                                {isReuploadingSalesOffer && (
                                  <Button
                                    type="button"
                                    variant="ghost"
                                    size="sm"
                                    className="text-xs text-gray-500 hover:text-gray-700 h-8 px-2 cursor-pointer"
                                    onClick={() => {
                                      setIsReuploadingSalesOffer(false);
                                      setSalesOfferFile(null);
                                    }}
                                  >
                                    {isAr ? "إلغاء" : "Cancel"}
                                  </Button>
                                )}
                              </div>

                              <input
                                type="file"
                                id="salesOfferUpload"
                                className="hidden"
                                accept="image/png,image/jpeg,image/jpg,image/webp"
                                multiple={false}
                                onChange={(e) => {
                                  const file = e.target.files?.[0];
                                  if (file) {
                                    if (!file.type.startsWith("image/")) {
                                      toast.error(
                                        isAr
                                          ? "يرجى اختيار صورة فقط بصيغة PNG أو JPG أو WEBP"
                                          : "Please select an image file only (PNG, JPG, WEBP)"
                                      );
                                      e.target.value = "";
                                      return;
                                    }
                                    if (file.size > 5 * 1024 * 1024) {
                                      toast.error(
                                        isAr
                                          ? "حجم الصورة كبير جداً، الحد الأقصى 5 ميجابايت"
                                          : "Image size is too large (max 5MB)"
                                      );
                                      e.target.value = "";
                                      return;
                                    }
                                    setSalesOfferFile(file);
                                    setIsReuploadingSalesOffer(true);
                                  }
                                  e.target.value = "";
                                }}
                              />
                              <label
                                htmlFor="salesOfferUpload"
                                className="flex items-center justify-center gap-2 p-4 border-2 border-dashed border-teal-300 bg-white rounded-lg cursor-pointer hover:border-teal-500 hover:bg-teal-50/50 transition-colors"
                              >
                                {salesOfferImagePreview ? (
                                  <div className="relative flex flex-col items-center justify-center w-full py-2">
                                    <div className="relative group max-w-sm">
                                      <img
                                        src={salesOfferImagePreview}
                                        alt="Sales Offer Preview"
                                        className="max-h-52 max-w-full rounded-lg object-contain border border-teal-200 shadow-sm"
                                      />
                                      <button
                                        type="button"
                                        onClick={(e) => {
                                          e.preventDefault();
                                          e.stopPropagation();
                                          setSalesOfferFile(null);
                                        }}
                                        className="absolute -top-2 -right-2 p-1.5 bg-red-600 hover:bg-red-700 text-white rounded-full shadow-md cursor-pointer"
                                        title={isAr ? "حذف" : "Remove"}
                                      >
                                        <X className="h-3.5 w-3.5" />
                                      </button>
                                    </div>
                                    <div className="flex items-center gap-2 mt-2 text-xs text-teal-900 font-medium">
                                      <span>{salesOfferFile?.name}</span>
                                      <span className="text-gray-400">
                                        ({(salesOfferFile?.size ? salesOfferFile.size / 1024 : 0).toFixed(1)} KB)
                                      </span>
                                    </div>
                                  </div>
                                ) : (
                                  <div className="text-center py-2">
                                    <ImageIcon className="h-8 w-8 text-teal-600 mx-auto mb-1.5" />
                                    <span className="text-sm font-semibold text-gray-800 block">
                                      {isAr ? "اضغط لاختيار صورة عرض المبيعات" : "Click to select sales offer image"}
                                    </span>
                                    <span className="text-xs text-gray-500 mt-1 block">
                                      {isAr
                                        ? "صورة واحدة فقط (PNG, JPG, WEBP) بحد أقصى 5 ميجابايت"
                                        : "Single image only (PNG, JPG, WEBP) — max 5 MB"}
                                    </span>
                                  </div>
                                )}
                              </label>

                              <div className="space-y-1">
                                <label className="text-xs font-medium text-gray-700 block">
                                  {t("reservations.approveDialog.commentsLabel")}
                                </label>
                                <textarea
                                  className="w-full min-h-[60px] p-2.5 text-xs bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none resize-y"
                                  placeholder={t("reservations.uploadOfferDialog.commentsPlaceholder")}
                                  value={adminComment}
                                  onChange={(e) => setAdminComment(e.target.value)}
                                />
                              </div>

                              <Button
                                className="w-full bg-teal-600 hover:bg-teal-700 text-white font-medium shadow-xs cursor-pointer"
                                onClick={() => {
                                  handleSalesOfferUpload();
                                  setIsReuploadingSalesOffer(false);
                                }}
                                disabled={!salesOfferFile || uploadSalesOfferMutation.isPending}
                              >
                                {uploadSalesOfferMutation.isPending ? (
                                  <>
                                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                    {t("reservations.actions.uploading")}
                                  </>
                                ) : (
                                  <>
                                    <Upload className="h-4 w-4 mr-2" />
                                    {isAr ? "رفع صورة عرض المبيعات" : "Upload Sales Offer Image"}
                                  </>
                                )}
                              </Button>
                            </div>
                          );
                        }

                         return (
                          <div className="mt-3 space-y-3">

                            {/* Waiting / Locked banner */}
                            <div className={`p-4 rounded-xl border flex flex-col gap-2 ${
                              stage.currentStatusType === "sales_offer_approval"
                                ? "bg-blue-50/70 border-blue-200/80"
                                : "bg-amber-50/70 border-amber-200/80"
                            }`}>
                              <div className="flex items-start gap-3">
                                <div className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 mt-0.5 border ${
                                  stage.currentStatusType === "sales_offer_approval"
                                    ? "bg-blue-100 border-blue-300"
                                    : "bg-amber-100 border-amber-300"
                                }`}>
                                  <Clock className={`h-4 w-4 animate-pulse ${
                                    stage.currentStatusType === "sales_offer_approval"
                                      ? "text-blue-600"
                                      : "text-amber-700"
                                  }`} />
                                </div>
                                <div className="flex-1">
                                  <div className="flex items-center gap-2 flex-wrap">
                                    <p className={`text-xs font-bold uppercase tracking-wider ${
                                      stage.currentStatusType === "sales_offer_approval"
                                        ? "text-blue-900"
                                        : "text-amber-900"
                                    }`}>
                                      {stage.currentStatusType === "sales_offer_approval"
                                        ? (isAr ? "في انتظار قبول العميل للعرض" : "Waiting for Client to Accept the Offer")
                                        : (isAr ? "في انتظار موافقة العميل" : "Waiting for Client Approval")}
                                    </p>
                                    <Badge className={`text-[10px] px-2 py-0.5 font-semibold ${
                                      stage.currentStatusType === "sales_offer_approval"
                                        ? "bg-blue-100 text-blue-800 border-blue-300"
                                        : "bg-amber-100 text-amber-800 border-amber-300"
                                    }`}>
                                      {stage.currentStatusType === "sales_offer_approval"
                                        ? (isAr ? "بانتظار القبول" : "Awaiting Acceptance")
                                        : (isAr ? "قيد الانتظار" : "Pending Approval")}
                                    </Badge>
                                    {stage.currentStatusType === "sales_offer_approval" && (
                                      <Badge className="bg-gray-100 text-gray-600 border-gray-300 text-[10px] px-2 py-0.5 font-semibold">
                                        🔒 {isAr ? "مقفل" : "Locked"}
                                      </Badge>
                                    )}
                                  </div>
                                  <p className={`text-xs mt-1 leading-relaxed ${
                                    stage.currentStatusType === "sales_offer_approval"
                                      ? "text-blue-800"
                                      : "text-amber-800"
                                  }`}>
                                    {stage.currentStatusType === "sales_offer_approval"
                                      ? (isAr
                                        ? "تم رفع العرض وإرساله للعميل. لا يمكن تعديل الصورة الآن. في انتظار قبول العميل للمتابعة إلى مرحلة الدفعة الأولى."
                                        : "The offer has been uploaded and sent to the client. No changes allowed at this stage. Waiting for the client to accept and proceed to down payment.")
                                      : (isAr
                                        ? "تم رفع صورة عرض المبيعات بنجاح. في انتظار موافقة العميل على العرض للانتقال إلى مرحلة الدفعة الأولى."
                                        : "Sales offer image uploaded successfully. Waiting for the client to approve the offer before moving to down payment.")}
                                  </p>
                                </div>
                              </div>
                            </div>
                          </div>
                        );
                      })()}



                      {stage.id === 3 && isPending && (() => {
                        const hasReceiptDoc = stage.documents && stage.documents.length > 0;
                         const isDownPaymentPending = stage.currentStatusType === "down_payment_pending";
                        const shouldShowApproveReject = isDownPaymentPending || (hasReceiptDoc && !isReuploadingDownPayment && !downPaymentFile);
                        const shouldShowPaymentUpload = !isDownPaymentPending && (!hasReceiptDoc || isReuploadingDownPayment || Boolean(downPaymentFile));

                        return (
                          <div className="mt-4 space-y-4">
                              {shouldShowPaymentUpload && (
                              <div className="p-4 bg-teal-50/40 rounded-xl border border-teal-200 space-y-3">
                                <div className="flex items-center justify-between">
                                  <div>
                                    <span className="text-xs font-bold uppercase tracking-wider text-teal-800 flex items-center gap-1.5">
                                      <ImageIcon className="h-4 w-4 text-teal-600" />
                                      {hasReceiptDoc
                                        ? (isAr ? "رفع إيصال جديد / تغيير إيصال الدفعة الأولى" : "Upload New Receipt / Replace Payment Receipt")
                                        : (isAr ? "رفع إيصال الدفعة الأولى" : "Upload Down Payment Receipt")}
                                    </span>
                                    <p className="text-xs text-gray-600 mt-0.5">
                                      {isAr
                                        ? "ارفع إيصال التحويل البنكي أو إثبات سداد الدفعة الأولى (صورة أو ملف PDF)."
                                        : "Upload the bank transfer receipt or proof of payment for the down payment (image or PDF)."}
                                    </p>
                                  </div>
                                  {hasReceiptDoc && (
                                    <Button
                                      type="button"
                                      variant="ghost"
                                      size="sm"
                                      className="text-xs text-gray-500 hover:text-gray-700 h-8 px-2 cursor-pointer"
                                      onClick={() => {
                                        setIsReuploadingDownPayment(false);
                                        setDownPaymentFile(null);
                                      }}
                                    >
                                      {isAr ? "إلغاء" : "Cancel"}
                                    </Button>
                                  )}
                                </div>

                                <input
                                  type="file"
                                  id="downPaymentUpload"
                                  className="hidden"
                                  accept="image/png,image/jpeg,image/jpg,image/webp,application/pdf"
                                  onChange={(e) => {
                                    const file = e.target.files?.[0];
                                    if (file) {
                                      if (file.size > 10 * 1024 * 1024) {
                                        toast.error(
                                          isAr
                                            ? "حجم الملف كبير جداً، الحد الأقصى 10 ميجابايت"
                                            : "File size is too large (max 10MB)"
                                        );
                                        e.target.value = "";
                                        return;
                                      }
                                      setDownPaymentFile(file);
                                      setIsReuploadingDownPayment(true);
                                    }
                                    e.target.value = "";
                                  }}
                                />
                                <label
                                  htmlFor="downPaymentUpload"
                                  className="flex items-center justify-center gap-2 p-4 border-2 border-dashed border-teal-300 bg-white rounded-lg cursor-pointer hover:border-teal-500 hover:bg-teal-50/50 transition-colors"
                                >
                                  {downPaymentPreview ? (
                                    <div className="relative flex flex-col items-center justify-center w-full py-2">
                                      <div className="relative group max-w-sm">
                                        <img
                                          src={downPaymentPreview}
                                          alt="Down Payment Receipt"
                                          className="max-h-52 max-w-full rounded-lg object-contain border border-teal-200 shadow-sm"
                                        />
                                        <button
                                          type="button"
                                          onClick={(e) => {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            setDownPaymentFile(null);
                                          }}
                                          className="absolute -top-2 -right-2 p-1.5 bg-red-600 hover:bg-red-700 text-white rounded-full shadow-md cursor-pointer"
                                          title={isAr ? "حذف" : "Remove"}
                                        >
                                          <X className="h-3.5 w-3.5" />
                                        </button>
                                      </div>
                                      <div className="flex items-center gap-2 mt-2 text-xs text-teal-900 font-medium">
                                        <span>{downPaymentFile?.name}</span>
                                        <span className="text-gray-400">
                                          ({(downPaymentFile?.size ? downPaymentFile.size / 1024 : 0).toFixed(1)} KB)
                                        </span>
                                      </div>
                                    </div>
                                  ) : downPaymentFile ? (
                                    <div className="flex items-center justify-between w-full p-2 bg-gray-50 rounded-lg">
                                      <div className="flex items-center gap-2">
                                        <FileText className="h-6 w-6 text-teal-600" />
                                        <span className="text-xs font-medium text-gray-800">{downPaymentFile.name}</span>
                                      </div>
                                      <button
                                        type="button"
                                        onClick={(e) => {
                                          e.preventDefault();
                                          e.stopPropagation();
                                          setDownPaymentFile(null);
                                        }}
                                        className="p-1 text-red-600 hover:text-red-700"
                                      >
                                        <X className="h-4 w-4" />
                                      </button>
                                    </div>
                                  ) : (
                                    <div className="text-center py-2">
                                      <Upload className="h-8 w-8 text-teal-600 mx-auto mb-1.5" />
                                      <span className="text-sm font-semibold text-gray-800 block">
                                        {isAr ? "اضغط لاختيار إيصال الدفعة الأولى" : "Click to select down payment receipt"}
                                      </span>
                                      <span className="text-xs text-gray-500 mt-1 block">
                                        {isAr
                                          ? "صور (PNG, JPG, WEBP) أو مستندات (PDF) بحد أقصى 10 ميجابايت"
                                          : "Images (PNG, JPG, WEBP) or PDF — max 10 MB"}
                                      </span>
                                    </div>
                                  )}
                                </label>

                                <div className="space-y-1">
                                  <label className="text-xs font-medium text-gray-700 block">
                                    {t("reservations.approveDialog.commentsLabel")}
                                  </label>
                                  <textarea
                                    className="w-full min-h-[60px] p-2.5 text-xs bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none resize-y"
                                    placeholder={t("reservations.approveDialog.commentsPlaceholder")}
                                    value={downPaymentComment}
                                    onChange={(e) => setDownPaymentComment(e.target.value)}
                                  />
                                </div>

                                <Button
                                  className="w-full bg-teal-600 hover:bg-teal-700 text-white font-medium shadow-xs cursor-pointer"
                                  onClick={handleDownPaymentUpload}
                                  disabled={!downPaymentFile || (uploadDownPaymentMutation && uploadDownPaymentMutation.isPending)}
                                >
                                  {uploadDownPaymentMutation && uploadDownPaymentMutation.isPending ? (
                                    <>
                                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                      {t("reservations.actions.uploading")}
                                    </>
                                  ) : (
                                    <>
                                      <Upload className="h-4 w-4 mr-2" />
                                      {isAr ? "رفع إيصال الدفعة الأولى" : "Upload Down Payment Receipt"}
                                    </>
                                  )}
                                </Button>
                              </div>
                            )}

                            {/* Verification & Approval Actions Section */}
                            {/* Verification & Approval Actions — shown when client uploaded receipt or down_payment_pending */}
                            {shouldShowApproveReject && (
                              <div className="space-y-3 p-4 bg-emerald-50/40 rounded-xl border border-emerald-200 shadow-2xs">
                                <div className="flex items-center justify-between">
                                  <div>
                                    <span className="text-xs font-bold uppercase tracking-wider text-emerald-800">
                                      {t("reservations.actions.approveDownPayment")}
                                    </span>
                                    <p className="text-xs text-gray-600 mt-0.5">
                                      {isDownPaymentPending
                                        ? (isAr ? "قام العميل برفع إيصال الدفعة. راجع الإيصال أدناه ثم وافق أو ارفض." : "The client has uploaded a payment receipt. Review it below then approve or reject.")
                                        : t("reservations.stages.downPaymentReviewSubtitle")}
                                    </p>
                                  </div>
                                  {!isDownPaymentPending && (
                                    <Button
                                      type="button"
                                      size="sm"
                                      variant="outline"
                                      onClick={() => setIsReuploadingDownPayment(true)}
                                      className="gap-1.5 border-teal-300 text-teal-700 hover:bg-teal-50 hover:text-teal-800 cursor-pointer h-7 text-xs font-medium"
                                    >
                                      <Upload className="h-3 w-3" />
                                      <span>{isAr ? "تغيير الإيصال" : "Change Receipt"}</span>
                                    </Button>
                                  )}
                                </div>


                                <div className="space-y-1">
                                  <label className="text-xs font-medium text-gray-700 block">
                                    {t("reservations.approveDialog.commentsLabel")}
                                  </label>
                                  <textarea
                                    className="w-full min-h-[60px] p-2.5 text-xs bg-white border border-gray-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none resize-y"
                                    placeholder={t("reservations.approveDialog.commentsPlaceholder")}
                                    value={adminComment}
                                    onChange={(e) => setAdminComment(e.target.value)}
                                  />
                                </div>

                                <div className="flex gap-2">
                                  <Button
                                    className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-medium shadow-xs cursor-pointer"
                                    disabled={approveDownPaymentMutation.isPending}
                                    onClick={handleApproveDownPaymentAction}
                                  >
                                    {approveDownPaymentMutation.isPending ? (
                                      <>
                                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                        {t("reservations.actions.approving")}
                                      </>
                                    ) : (
                                      t("reservations.actions.approveDownPayment")
                                    )}
                                  </Button>
                                  <Button
                                    className="bg-rose-600 hover:bg-rose-700 text-white font-medium px-5 cursor-pointer"
                                    disabled={declineMutation.isPending}
                                    onClick={() =>
                                      declineMutation.mutate({
                                        comments: adminComment,
                                        reservation_status_type: "DOWN_PAYMENT",
                                      })
                                    }
                                  >
                                    {declineMutation.isPending ? (
                                      <>
                                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                        {t("reservations.actions.declining")}
                                      </>
                                    ) : (
                                      t("reservations.actions.decline")
                                    )}
                                  </Button>
                                </div>
                              </div>
                            )}

                          </div>
                        );
                      })()}

                      {/* Stage 4: SPA Upload */}
                      {stage.id === 4 && isPending && (
                        <div className="mt-4">
                          <input
                            type="file"
                            id="spaUpload"
                            className="hidden"
                            accept="image/*,.pdf,.doc,.docx"
                            onChange={(e) => {
                              const file = e.target.files?.[0];
                              if (file) {
                                setSpaFile(file);
                              }
                            }}
                          />
                          <label
                            htmlFor="spaUpload"
                            className="flex items-center justify-center gap-2 p-3 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-teal-500 hover:bg-teal-50 transition-colors"
                          >
                            {spaFile ? (
                              <>
                                <File className="h-5 w-5 text-teal-600" />
                                <span className="text-sm font-medium text-teal-600">
                                  {spaFile.name}
                                </span>
                              </>
                            ) : (
                              <>
                                <Upload className="h-5 w-5 text-gray-400" />
                                <span className="text-sm font-medium text-gray-500">
                                  {t("reservations.uploadOfferDialog.clickToSelect")}
                                </span>
                              </>
                            )}
                          </label>
                          {spaFile && (
                            <Button
                              className="w-full mt-2 bg-teal-600 hover:bg-teal-700 text-white"
                              onClick={handleSpaUpload}
                              disabled={uploadSPAMutation.isPending}
                            >
                              {uploadSPAMutation.isPending ? (
                                <>
                                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                                  {t("reservations.actions.uploading")}
                                </>
                              ) : (
                                <>
                                  <Upload className="h-4 w-4 mr-2" />
                                  {t("reservations.actions.uploadSPA")}
                                </>
                              )}
                            </Button>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                ) : null}

                {stage.comments && stage.comments.length > 0 && (
                  <div className="space-y-2 pt-2 border-t border-gray-100">
                    <h4 className="text-xs font-semibold text-gray-700">
                      {t("reservations.details.commentsHistory")}
                    </h4>
                    {stage.comments.map((comment: any, cIdx: number) => (
                      <div key={cIdx} className="bg-gray-50 p-3 rounded-lg border border-gray-200 text-xs">
                        <div className="flex items-center justify-between text-gray-500 mb-1">
                          <span className="font-medium text-gray-700">{comment.author}</span>
                          <span>{comment.date ? new Date(comment.date).toLocaleDateString() : ""}</span>
                        </div>
                        <p className="text-gray-800">{comment.text}</p>
                      </div>
                    ))}
                  </div>
                )}
                {stage.id === 1 && !isStage1Complete && !isStage1Approved && stage.currentStatus === "in_process" && (
                  <div className="space-y-4 pt-4 border-t border-gray-100">
                    <div className="space-y-2">
                      <label className="text-sm font-medium text-gray-700">
                        {t("reservations.approveDialog.commentsLabel")}
                      </label>
                      <textarea
                        className="w-full min-h-[80px] p-3 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none resize-y"
                        placeholder={t("reservations.approveDialog.commentsPlaceholder")}
                        value={adminComment}
                        onChange={(e) => setAdminComment(e.target.value)}
                      />
                    </div>
                    <div className="flex gap-2 pt-2">
                      <Button
                        className="flex-1 bg-teal-600 hover:bg-teal-700 text-white font-medium shadow-xs"
                        disabled={approveMutation.isPending}
                        onClick={handleApprove}
                      >
                        {approveMutation.isPending ? (
                          <>
                            <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                            {t("reservations.actions.approving")}
                          </>
                        ) : (
                          t("reservations.actions.approveAndMoveToStage2")
                        )}
                      </Button>
                      <Button
                        className="bg-rose-600 hover:bg-rose-700 text-white font-medium px-6"
                        disabled={declineMutation.isPending}
                        onClick={() => {
                          declineMutation.mutate({
                            comments: adminComment,
                            reservation_status_type: "IDENTIFICATION",
                          });
                        }}
                      >
                        {declineMutation.isPending ? (
                          <>
                            <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                            {t("reservations.actions.declining")}
                          </>
                        ) : (
                          t("reservations.actions.decline")
                        )}
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        );
        });
      })()}
    </div>
  );
}